import * as anchor from "@coral-xyz/anchor";
import {
  Connection,
  PublicKey,
  VersionedTransactionResponse,
} from "@solana/web3.js";
import {
  TOKEN_2022_PROGRAM_ID,
  getAccount,
  getAssociatedTokenAddressSync,
  getMint,
} from "@solana/spl-token";
import demoJson from "./demo.json";
// Generated by `anchor build` (target/idl + target/types). Refresh both after program changes.
import idlJson from "./rulecash.json";
import type { Rulecash } from "./rulecash.types";

export type Demo = {
  cluster: string;
  programId: string;
  issuer: string;
  rulecashMint: string;
  usdcMint: string;
  usdcTokenProgram: string;
  grant: string;
  vault: string;
  dailyCap: number;
  allowedCategories: number;
  grantees: { name: string; wallet: string }[];
  merchants: { name: string; wallet: string; category: number; perTxCap: number; blockedByGrant?: boolean }[];
};

export const DEMO = demoJson as Demo;
export const RPC_URL = process.env.NEXT_PUBLIC_RPC_URL ?? "https://api.devnet.solana.com";
export const PROGRAM_ID = new PublicKey(DEMO.programId);
export const MINT = new PublicKey(DEMO.rulecashMint);
export const GRANT = new PublicKey(DEMO.grant);
export const VAULT = new PublicKey(DEMO.vault);
export const USDC_MINT = new PublicKey(DEMO.usdcMint);
export const USDC_PROGRAM = new PublicKey(DEMO.usdcTokenProgram);
export const RULECASH_DECIMALS = 6;

export const CATEGORY_NAMES: Record<number, string> = {
  0: "Food",
  1: "Hardware",
  5: "Casino",
};

export const connection = new Connection(RPC_URL, "confirmed");

// Read-only Anchor program: no wallet needed for account fetches.
const readonlyProvider = new anchor.AnchorProvider(
  connection,
  {
    publicKey: PublicKey.default,
    signTransaction: async () => {
      throw new Error("read-only provider");
    },
    signAllTransactions: async () => {
      throw new Error("read-only provider");
    },
  },
  { commitment: "confirmed" }
);
export const readonlyProgram = new anchor.Program<Rulecash>(idlJson as Rulecash, readonlyProvider);
const ixCoder = new anchor.BorshInstructionCoder(idlJson as anchor.Idl);

export const rcAta = (owner: PublicKey) =>
  getAssociatedTokenAddressSync(MINT, owner, false, TOKEN_2022_PROGRAM_ID);

export const merchantPda = (wallet: PublicKey) =>
  PublicKey.findProgramAddressSync(
    [Buffer.from("merchant"), MINT.toBuffer(), wallet.toBuffer()],
    new PublicKey(DEMO.programId)
  )[0];

export type DashboardState = {
  dailyCap: number;
  allowedCategories: number;
  vaultUsdc: number;
  supply: number;
  merchants: { wallet: string; category: number; perTxCap: number; active: boolean }[];
};

export async function loadDashboard(): Promise<DashboardState> {
  const grant = await readonlyProgram.account.grant.fetch(GRANT);
  const vault = await getAccount(connection, VAULT, "confirmed", USDC_PROGRAM);
  const mintInfo = await getMint(connection, MINT, "confirmed", TOKEN_2022_PROGRAM_ID);
  const merchantAccounts = await readonlyProgram.account.merchant.all([
    { memcmp: { offset: 8, bytes: MINT.toBase58() } },
  ]);
  return {
    dailyCap: Number(grant.dailyCap.toString()) / 10 ** RULECASH_DECIMALS,
    allowedCategories: grant.allowedCategories,
    vaultUsdc: Number(vault.amount) / 10 ** RULECASH_DECIMALS,
    supply: Number(mintInfo.supply) / 10 ** RULECASH_DECIMALS,
    merchants: merchantAccounts.map(({ account }) => ({
      wallet: account.wallet.toBase58(),
      category: account.category,
      perTxCap: Number(account.perTxCap.toString()) / 10 ** RULECASH_DECIMALS,
      active: account.active,
    })),
  };
}

export type FeedKind = "paid" | "blocked" | "funded" | "redeemed" | "failed";

export type FeedItem = {
  signature: string;
  time: number | null;
  kind: FeedKind;
  amount: number | null;
  detail: string | null;
};

const TRANSFER_CHECKED = 12;

// Classify one transaction by its top-level instructions. Setup txs (mint, grant, merchants,
// ATA creation) return null so the feed only shows payments, funding and redemptions.
function classify(tx: VersionedTransactionResponse, ok: boolean): Omit<FeedItem, "signature" | "time"> | null {
  const msg = tx.transaction.message;
  const keys = msg.getAccountKeys({ accountKeysFromLookups: tx.meta?.loadedAddresses });
  const logs = (tx.meta?.logMessages ?? []).join("\n");
  const errorCode = logs.match(/Error Code: (\w+)/)?.[1] ?? null;

  for (const ix of msg.compiledInstructions) {
    const programId = keys.get(ix.programIdIndex);
    if (!programId) continue;
    const data = Buffer.from(ix.data);

    if (programId.equals(TOKEN_2022_PROGRAM_ID) && data[0] === TRANSFER_CHECKED) {
      const amount = Number(data.readBigUInt64LE(1)) / 10 ** RULECASH_DECIMALS;
      return ok
        ? { kind: "paid", amount, detail: null }
        : { kind: "blocked", amount, detail: errorCode ?? "Rejected" };
    }

    if (programId.equals(PROGRAM_ID)) {
      const decoded = ixCoder.decode(data);
      if (!decoded) continue;
      if (decoded.name === "depositAndMint" || decoded.name === "deposit_and_mint") {
        const amount = Number((decoded.data as { amount: anchor.BN }).amount.toString()) / 10 ** RULECASH_DECIMALS;
        return ok
          ? { kind: "funded", amount, detail: null }
          : { kind: "failed", amount, detail: `fund failed: ${errorCode ?? "error"}` };
      }
      if (decoded.name === "redeem") {
        const amount = Number((decoded.data as { amount: anchor.BN }).amount.toString()) / 10 ** RULECASH_DECIMALS;
        return ok
          ? { kind: "redeemed", amount, detail: null }
          : { kind: "failed", amount, detail: `redeem failed: ${errorCode ?? "error"}` };
      }
    }
  }
  return null; // setup or unrelated
}

export async function loadFeed(limit = 10): Promise<FeedItem[]> {
  const sigs = await connection.getSignaturesForAddress(MINT, { limit });
  const results = await Promise.all(
    sigs.map(async (s): Promise<FeedItem | null> => {
      const tx = await connection.getTransaction(s.signature, {
        commitment: "confirmed",
        maxSupportedTransactionVersion: 0,
      });
      if (!tx) return null;
      const ok = !tx.meta?.err;
      const info = classify(tx, ok);
      if (!info) return null;
      return { signature: s.signature, time: s.blockTime ?? null, ...info };
    })
  );
  return results.filter((r): r is FeedItem => r !== null);
}

export const spendPda = (owner: PublicKey) =>
  PublicKey.findProgramAddressSync(
    [Buffer.from("spend"), MINT.toBuffer(), owner.toBuffer()],
    PROGRAM_ID
  )[0];

export const usdcAta = (owner: PublicKey) =>
  getAssociatedTokenAddressSync(USDC_MINT, owner, false, USDC_PROGRAM);

// Spend resets each UTC day, so only today's counter counts against the cap.
export async function loadSpentToday(owner: PublicKey): Promise<number> {
  const spend = await readonlyProgram.account.spend.fetchNullable(spendPda(owner));
  if (!spend) return 0;
  const today = Math.floor(Date.now() / 1000 / 86400);
  if (Number(spend.dayIndex.toString()) !== today) return 0;
  return Number(spend.spentToday.toString()) / 10 ** RULECASH_DECIMALS;
}

export async function hasSpendAccount(owner: PublicKey): Promise<boolean> {
  return (await readonlyProgram.account.spend.fetchNullable(spendPda(owner))) !== null;
}
